        <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z"/></svg>
      </div>
      <div>
        <h3 class="text-lg font-bold text-amber-900 mb-2">Key Point</h3>
        <p class="text-amber-800 text-lg">Use results to improve, not to judge. One email is a data point - patterns over time show you what works.</p>
      </div>
    </div>
  </div>

  <!-- Action Steps -->
  <div class="bg-gradient-to-br from-emerald-50 to-teal-50 rounded-2xl p-6 border-2 border-emerald-200">
    <div class="flex items-center gap-3 mb-5">
      <div class="w-12 h-12 rounded-xl bg-emerald-100 flex items-center justify-center">
        <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"/></svg>
      </div>
      <h3 class="text-xl font-bold text-emerald-900">Action Steps — Create Your Follow-Up Template</h3>
    </div>
    
    <div class="space-y-4">
      
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">1</div>
        <div>
          <p class="font-semibold text-slate-900">Wait 24-48 hours after sending</p>
          <p class="text-slate-600 text-sm">Give people time to open and engage</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">2</div>
        <div>
          <p class="font-semibold text-slate-900">Review your campaign results</p>
          <p class="text-slate-600 text-sm">Check opens, clicks, and other metrics in LeadProspectrr</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">3</div>
        <div>
          <p class="font-semibold text-slate-900">Note one improvement</p>
          <p class="text-slate-600 text-sm">What will you do differently next time?</p>
        </div>
      </div>
    </div>
  </div>
</div>',
      title = 'Understand Campaign Results',
      lesson_number = 8,
      sort_order = 8,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: Understand Campaign Results';
  END IF;

END $$;


-- Insert Quiz Questions for Lesson: Understand Campaign Results

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 3 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 3 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'understand-campaign-results' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson understand-campaign-results not found in module 3';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What does a high open rate but low click rate indicate?', 
    '["Your subject line is ineffective","Your call-to-action or offer isn''t compelling enough","Your email is too short","You sent it at the wrong time of day"]'::jsonb,
    'Your call-to-action or offer isn''t compelling enough',
    'If people open but don''t click, your subject line worked (they opened) but your content or CTA didn''t motivate action.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do if your open rate is low?', 
    '["Send the same email again immediately","Work on improving your subject line","Add more links to the email","Send to more people"]'::jsonb,
    'Work on improving your subject line',
    'Low open rates usually indicate the subject line isn''t compelling enough. Test different subject lines to see what resonates with your audience.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'How should you interpret results from a single email campaign?', 
    '["Judge it harshly if it doesn''t perform perfectly","Use it as one data point and look for patterns over time","Delete the email and never send campaigns again","Immediately change your entire business strategy"]'::jsonb,
    'Use it as one data point and look for patterns over time',
    'One email is a single data point. Look for patterns across multiple campaigns to understand what works for your specific audience.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
